-- O Garimpeiro parava nos primeiros resultados: acrescenta a orientação de cobertura (só se ainda não tiver).
UPDATE "AgentProfile" SET "description" = "description" || ' COBERTURA: não pare nos primeiros resultados. Liste as cidades e distritos dentro do raio a partir da cidade-base e pesquise CIDADE POR CIDADE e SEGMENTO POR SEGMENTO (variando os termos: nome do segmento + cidade, ''perto de'', bairros, diretórios públicos de empresas e mapas), até registrar o limite de leads novos da execução ou esgotar de verdade as fontes. Se uma empresa for recusada (duplicada, fora do raio), siga para a próxima — não conte como falha. No relatório final liste, por cidade e segmento, quantas encontrou, quantas recusou e por quê, e quais fontes falharam.' WHERE "team" = 'COMERCIAL' AND "slug" = 'id-garimpeiro' AND "description" NOT LIKE '%COBERTURA:%';
UPDATE "AgentRoutine" SET "prompt" = 'Rotina de prospecção. Leia configuracao_prospeccao e registre novas empresas dos segmentos e do raio configurados, pesquisando cidade por cidade e segmento por segmento, até o limite de leads novos por execução ou até esgotar as fontes. Não repita empresas já cadastradas. Seja econômico e termine quando o trabalho pedido estiver feito; se não houver nada a fazer, responda em uma linha.' WHERE "name" = 'Prospecção de empresas' AND "prompt" LIKE 'Rotina de prospecção. Leia configuracao_prospeccao e registre novas empresas dos segmentos e do raio configurados, até o limite%';
